begin;
create table if not exists public.ls_read52_state(user_id uuid references auth.users(id) on delete cascade, peer uuid not null, is_group boolean not null, last_id bigint not null default 0, primary key(user_id,peer,is_group));
alter table public.ls_read52_state enable row level security;
revoke all on public.ls_read52_state from anon,authenticated;
create or replace function public.ls_profiles52() returns table(peer uuid,accepted boolean,incoming boolean,display_name text,image text,bio text) language sql stable security definer set search_path='' as $$ select f.peer,f.accepted,f.incoming,f.display_name,case when f.accepted then s.data->'profile'->>'image' end,case when f.accepted then s.data->'profile'->>'bio' end from public.ls_friends_named() f left join public.learnspot_state s on s.user_id=f.peer where auth.uid() is not null $$;
create or replace function public.ls_unread52() returns table(peer uuid,is_group boolean,unread bigint) language sql stable security definer set search_path='' as $$ select m.sender,false,count(*) from public.ls_messages m left join public.ls_read52_state r on r.user_id=auth.uid() and r.peer=m.sender and not r.is_group where m.recipient=auth.uid() and m.id>coalesce(r.last_id,0) group by m.sender union all select m.group_id,true,count(*) from public.ls_group_messages m join public.ls_group_members g on g.group_id=m.group_id and g.member=auth.uid() left join public.ls_read52_state r on r.user_id=auth.uid() and r.peer=m.group_id and r.is_group where m.sender<>auth.uid() and m.id>coalesce(r.last_id,0) group by m.group_id $$;
create or replace function public.ls_read52(peer_id uuid,is_group boolean) returns void language plpgsql security definer set search_path='' as $$ declare n bigint; begin if auth.uid() is null then return; end if; if is_group then select max(m.id) into n from public.ls_group_messages m where m.group_id=peer_id and exists(select 1 from public.ls_group_members g where g.group_id=peer_id and g.member=auth.uid()); else select max(m.id) into n from public.ls_messages m where m.sender=peer_id and m.recipient=auth.uid(); end if; insert into public.ls_read52_state values(auth.uid(),peer_id,is_group,coalesce(n,0)) on conflict on constraint ls_read52_state_pkey do update set last_id=greatest(ls_read52_state.last_id,excluded.last_id); end $$;
revoke all on function public.ls_profiles52(),public.ls_unread52(),public.ls_read52(uuid,boolean) from public,anon;
grant execute on function public.ls_profiles52(),public.ls_unread52(),public.ls_read52(uuid,boolean) to authenticated;
notify pgrst,'reload schema';
commit;
